class TrieNode:
    """A node in a trie."""

    def __init__(self) -> None:
        """Initialize an empty node."""
        self.children: dict[str, "TrieNode"] = {}
        self.is_end_of_word: bool = False


class Trie:
    """A prefix tree for storing and retrieving words."""

    def __init__(self) -> None:
        """Initialize an empty trie."""
        self.root: TrieNode = TrieNode()

    def insert(self, word: str) -> None:
        """Insert a word into the trie."""
        node = self.root

        for character in word:
            if character not in node.children:
                node.children[character] = TrieNode()
            node = node.children[character]

        node.is_end_of_word = True

    def search(self, word: str) -> bool:
        """Return whether an exact word exists in the trie."""
        node = self.root

        for character in word:
            if character not in node.children:
                return False
            node = node.children[character]

        return node.is_end_of_word

    def starts_with(self, prefix: str) -> bool:
        """Return whether any inserted word starts with the prefix."""
        node = self.root

        for character in prefix:
            if character not in node.children:
                return False
            node = node.children[character]

        return node.is_end_of_word or bool(node.children)

    def autocomplete(
        self, prefix: str, max_results: int = 5
    ) -> list[str]:
        """Return alphabetically sorted completions for a prefix."""
        if max_results <= 0:
            return []

        node = self.root

        for character in prefix:
            if character not in node.children:
                return []
            node = node.children[character]

        results: list[str] = []

        def dfs(current_node: TrieNode, current_word: str) -> None:
            if len(results) >= max_results:
                return

            if current_node.is_end_of_word:
                results.append(current_word)

            for character in sorted(current_node.children):
                if len(results) >= max_results:
                    break
                dfs(
                    current_node.children[character],
                    current_word + character,
                )

        dfs(node, prefix)
        return results


if __name__ == "__main__":
    trie = Trie()

    words = [
        "apple",
        "app",
        "application",
        "apt",
        "bat",
        "batch",
        "bath",
    ]

    for word in words:
        trie.insert(word)

    print('search("app") =>', trie.search("app"))
    print('search("ap") =>', trie.search("ap"))
    print('starts_with("ap") =>', trie.starts_with("ap"))
    print('autocomplete("app") =>', trie.autocomplete("app"))
    print('autocomplete("bat") =>', trie.autocomplete("bat"))
    print('autocomplete("xyz") =>', trie.autocomplete("xyz"))
